/**
 * Couche A — banque de questions vrai/faux pour "Géométrie dans l'espace" (gen66). 7 thèmes qui
 * suivent les sections du cours (`src/content/chapters/4e/geometrie-dans-espace.ts`), 35 affirmations
 * chacun (18 vraies, 17 fausses).
 *
 * Réécrite à l'audit du chapitre 8 (points 44 à 46) : l'ancienne banque (3 thèmes, un par générateur
 * gen39-41) décrivait pour moitié l'interface des générateurs (« écran », « candidat », « gabarit »,
 * « boucle »…) au lieu du cours, contenait des affirmations fausses (une ombre qui « casse » sur
 * plusieurs obstacles successifs, « les deux extrémités » d'une droite…) et ignorait la perspective
 * cavalière, les plans, le parallélisme, le point de percée et la perspective centrale. Chaque
 * affirmation est désormais autonome (aucun renvoi à une question voisine, l'ordre étant mélangé),
 * sans indice entre parenthèses, et se vérifie d'un coup d'œil — jamais un calcul en plusieurs
 * étapes (`.claude/rules/quiz-generators.md`).
 *
 * Convention du cube ABCDEFGH, identique au cours : ABCD est la face du dessous, EFGH celle du
 * dessus, E au-dessus de A, F au-dessus de B, G au-dessus de C, H au-dessus de D.
 */
import type { QuestionVraiFaux, VarianteQuizGeometrieEspace } from "../../core/quizGeometrieEspace.types";

const PERSPECTIVE_CAVALIERE: QuestionVraiFaux[] = [
  { enonce: "En perspective cavalière, l'axe x (la largeur) se dessine horizontalement et à l'échelle réelle.", reponse: true, justification: "C'est la première règle de la convention : x reste horizontal et n'est pas réduit." },
  { enonce: "En perspective cavalière, l'axe z (la hauteur) se dessine verticalement et à l'échelle réelle.", reponse: true, justification: "La hauteur n'est ni inclinée ni réduite : seule la profondeur l'est." },
  { enonce: "En perspective cavalière, l'axe y (la profondeur) se dessine en diagonale, à 45° de l'horizontale.", reponse: true, justification: "C'est la direction choisie par la convention pour suggérer ce qui « rentre » dans la feuille." },
  { enonce: "En perspective cavalière, une longueur portée par l'axe y est dessinée deux fois plus courte qu'en réalité.", reponse: true, justification: "La profondeur est réduite de moitié ; sans cette réduction, le solide paraîtrait étiré vers l'arrière." },
  { enonce: "Une arête cachée par le solide se trace en pointillé.", reponse: true, justification: "Le pointillé indique qu'on ne la verrait pas de face : elle reste dessinée, mais distinguée des arêtes visibles." },
  { enonce: "Deux arêtes parallèles d'un solide restent parallèles sur un dessin en perspective cavalière.", reponse: true, justification: "La perspective cavalière conserve le parallélisme, contrairement à la perspective centrale." },
  { enonce: "La face avant d'un cube, parallèle à la feuille, se dessine comme un vrai carré.", reponse: true, justification: "Cette face n'utilise que les axes x et z, tous deux à l'échelle réelle et perpendiculaires sur le dessin." },
  { enonce: "La face du dessus d'un cube se dessine comme un parallélogramme, pas comme un carré.", reponse: true, justification: "Elle contient la direction y, dessinée à 45° et réduite de moitié : ses angles droits ne sont plus droits sur le dessin." },
  { enonce: "En perspective cavalière, une arête de profondeur longue de 6 cm se dessine avec une longueur de 3 cm.", reponse: true, justification: "La profondeur est réduite de moitié : 6 ÷ 2 = 3." },
  { enonce: "On ne mesure jamais une longueur en profondeur à la règle sur un dessin en perspective cavalière.", reponse: true, justification: "La réduction de moitié fausse la lecture : on raisonne sur les sommets nommés, pas sur des distances lues à l'œil." },
  { enonce: "Le cube est un cas particulier de parallélépipède.", reponse: true, justification: "Un cube est un parallélépipède dont toutes les arêtes ont la même longueur." },
  { enonce: "Un tétraèdre a quatre sommets et quatre faces triangulaires.", reponse: true, justification: "C'est sa définition : 4 sommets, 4 faces triangulaires et 6 arêtes." },
  { enonce: "Un prisme possède deux faces parallèles et superposables, reliées par des rectangles.", reponse: true, justification: "C'est la description du prisme donnée dans le cours." },
  { enonce: "La perspective cavalière est une convention : tous les dessins qui la suivent appliquent les mêmes règles.", reponse: true, justification: "Une convention fixée une fois pour toutes rend les dessins lisibles et comparables d'un exercice à l'autre." },
  { enonce: "Sur un dessin en perspective cavalière, un angle droit de la face du dessus d'un cube n'apparaît pas comme un angle droit.", reponse: true, justification: "La face du dessus devient un parallélogramme : ses angles droits apparaissent à 45° ou à 135°." },
  { enonce: "Pour raisonner sur un solide dessiné en perspective cavalière, on s'appuie sur les sommets nommés et sur leurs relations : appartenance, parallélisme, intersection.", reponse: true, justification: "Ces relations se lisent de façon fiable sur le dessin, contrairement aux longueurs en profondeur." },
  { enonce: "Dessiner un solide en perspective cavalière ne demande aucun point de fuite.", reponse: true, justification: "Les points de fuite appartiennent à la perspective centrale ; la cavalière garde les parallèles parallèles." },
  { enonce: "La perspective centrale est plus proche de ce que voit l'œil que la perspective cavalière.", reponse: true, justification: "Elle imite ce que capture un œil ou un objectif photo, mais elle est plus lourde à construire à la main." },
  { enonce: "En perspective cavalière, l'axe z (la hauteur) est réduit de moitié.", reponse: false, justification: "Seul l'axe y (la profondeur) est réduit de moitié ; la hauteur reste à l'échelle réelle." },
  { enonce: "En perspective cavalière, l'axe y (la profondeur) se dessine à l'échelle réelle, comme les deux autres axes.", reponse: false, justification: "La profondeur est la seule direction réduite de moitié." },
  { enonce: "En perspective cavalière, l'axe y (la profondeur) se dessine verticalement.", reponse: false, justification: "La verticale est réservée à la hauteur z ; la profondeur part en diagonale, à 45°." },
  { enonce: "Une arête cachée par le solide se trace en trait plein, comme les autres arêtes.", reponse: false, justification: "Une arête cachée se trace toujours en pointillé." },
  { enonce: "Deux arêtes parallèles d'un solide peuvent se couper sur un dessin en perspective cavalière.", reponse: false, justification: "La perspective cavalière conserve le parallélisme : deux arêtes parallèles restent parallèles sur le dessin." },
  { enonce: "Sur un dessin en perspective cavalière, toutes les faces d'un cube apparaissent comme des carrés.", reponse: false, justification: "Seules les faces avant et arrière sont des carrés ; les faces qui contiennent la profondeur deviennent des parallélogrammes." },
  { enonce: "En perspective cavalière, une arête de profondeur longue de 6 cm se dessine avec une longueur de 12 cm.", reponse: false, justification: "La profondeur est réduite de moitié, pas doublée : elle se dessine avec 3 cm." },
  { enonce: "Deux arêtes de même longueur réelle ont toujours la même longueur sur un dessin en perspective cavalière.", reponse: false, justification: "Une arête de profondeur est dessinée deux fois plus courte qu'une arête de largeur ou de hauteur de même longueur." },
  { enonce: "Si deux segments ont la même longueur sur un dessin en perspective cavalière, ils ont forcément la même longueur dans la réalité.", reponse: false, justification: "Un segment de profondeur dessiné est deux fois plus court que le vrai : deux longueurs égales sur le dessin peuvent être différentes en réalité." },
  { enonce: "Un tétraèdre a six faces.", reponse: false, justification: "Un tétraèdre a quatre faces triangulaires ; ce sont ses arêtes qui sont au nombre de six." },
  { enonce: "Un cube n'est pas un parallélépipède.", reponse: false, justification: "Un cube est un parallélépipède particulier, dont toutes les arêtes ont la même longueur." },
  { enonce: "Un tétraèdre possède deux faces parallèles.", reponse: false, justification: "Deux faces d'un tétraèdre ont toujours une arête commune : elles ne sont jamais parallèles." },
  { enonce: "En perspective cavalière, les arêtes parallèles d'un solide convergent vers un point de fuite.", reponse: false, justification: "C'est le propre de la perspective centrale ; la cavalière conserve le parallélisme." },
  { enonce: "En perspective cavalière, la réduction de moitié s'applique aux hauteurs, pour que le solide ne paraisse pas trop haut.", reponse: false, justification: "La réduction s'applique à la profondeur, pour que le solide ne paraisse pas étiré vers l'arrière." },
  { enonce: "La perspective cavalière ne permet de dessiner que des cubes.", reponse: false, justification: "Elle sert pour tous les solides du chapitre : parallélépipède, cube, prisme, tétraèdre…" },
  { enonce: "Sur un dessin en perspective cavalière, l'angle droit entre deux arêtes de la face avant d'un cube se dessine comme un angle de 45°.", reponse: false, justification: "La face avant n'utilise que x et z, dessinés perpendiculaires et à l'échelle : son angle droit reste droit." },
  { enonce: "La perspective cavalière est plus fidèle à la vision humaine que la perspective centrale.", reponse: false, justification: "C'est l'inverse : la perspective centrale imite l'œil, la cavalière est choisie parce qu'elle est plus simple et conserve le parallélisme." },
];

